<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Sorting Algorithm Visualizer</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #151d33;
      --accent: #61dafb;
      --bar: #8b5cf6;
      --text: #e8edf8;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      background: radial-gradient(circle at top, #1e2a4b, var(--bg) 60%);
      color: var(--text);
      font-family: Arial, sans-serif;
    }

    main {
      width: min(900px, 94vw);
      padding: 28px;
      border: 1px solid #2d3a5e;
      border-radius: 18px;
      background: rgba(21, 29, 51, .92);
      box-shadow: 0 18px 50px rgba(0, 0, 0, .35);
    }

    h1 {
      margin: 0 0 8px;
      font-size: clamp(1.4rem, 4vw, 2rem);
    }

    p {
      margin: 0 0 22px;
      color: #aeb9d5;
    }

    #bars {
      height: 330px;
      display: flex;
      align-items: end;
      gap: 5px;
      padding: 14px;
      overflow: hidden;
      border-radius: 12px;
      background: #090e1c;
      border: 1px solid #273354;
    }

    .bar {
      flex: 1 1 0;
      min-width: 3px;
      background: linear-gradient(to top, #6d28d9, var(--accent));
      border-radius: 4px 4px 0 0;
      transition: height 100ms ease, background 100ms ease;
    }

    .bar:hover {
      background: linear-gradient(to top, #a855f7, #b5f3ff);
    }

    .controls {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      margin-top: 20px;
    }

    button {
      border: 0;
      border-radius: 9px;
      padding: 10px 16px;
      cursor: pointer;
      color: #08101d;
      background: var(--accent);
      font-weight: 700;
      font-size: .95rem;
    }

    button:hover { filter: brightness(1.12); }
    button:disabled { cursor: wait; opacity: .55; }
    #shuffle { background: #a78bfa; }
    #reset { background: #cbd5e1; }
  </style>
</head>
<body>
  <main>
    <h1>Sorting Algorithm Visualizer</h1>
    <p>Bubble sort, animated one comparison at a time.</p>
    <div id="bars" aria-label="Array bars"></div>
    <div class="controls">
      <button id="sort" type="button">Sort</button>
      <button id="shuffle" type="button">Shuffle</button>
      <button id="reset" type="button">Reset</button>
    </div>
  </main>

  <script>
    (() => {
      const bars = document.getElementById("bars");
      const sortButton = document.getElementById("sort");
      const shuffleButton = document.getElementById("shuffle");
      const resetButton = document.getElementById("reset");

      const initial = [42, 12, 78, 25, 63, 8, 91, 36, 55, 19, 84, 31, 70, 47, 5, 67, 28, 96, 14, 59];
      let values = initial.slice();
      let pass = 0;
      let index = 0;
      let timer = null;

      function draw() {
        bars.replaceChildren();
        const max = Math.max(...values, 1);

        values.forEach((value) => {
          const bar = document.createElement("div");
          bar.className = "bar";
          bar.style.height = `${Math.max(2, (value / max) * 100)}%`;
          bar.title = String(value);
          bars.appendChild(bar);
        });
      }

      function resetSortState() {
        pass = 0;
        index = 0;
      }

      function isSorted() {
        for (let i = 1; i < values.length; i++) {
          if (values[i - 1] > values[i]) return false;
        }
        return true;
      }

      // Performs one bubble-sort comparison and redraws the bars.
      function sortStep() {
        if (values.length < 2 || isSorted()) {
          draw();
          return true;
        }

        const lastComparison = values.length - 1 - pass;
        if (values[index] > values[index + 1]) {
          [values[index], values[index + 1]] = [values[index + 1], values[index]];
        }

        index++;
        if (index >= lastComparison) {
          pass++;
          index = 0;
        }

        draw();
        return pass >= values.length - 1 || isSorted();
      }

      function stopAnimation() {
        if (timer !== null) {
          clearInterval(timer);
          timer = null;
        }
        sortButton.disabled = false;
        shuffleButton.disabled = false;
        resetButton.disabled = false;
      }

      function animateSort() {
        if (timer !== null || isSorted()) {
          draw();
          return;
        }

        sortButton.disabled = true;
        shuffleButton.disabled = true;
        resetButton.disabled = true;

        timer = setInterval(() => {
          if (sortStep()) stopAnimation();
        }, 70);
      }

      function shuffle() {
        stopAnimation();
        for (let i = values.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [values[i], values[j]] = [values[j], values[i]];
        }
        resetSortState();
        draw();
      }

      window.viz = {
        array() {
          return values.slice();
        },
        setArray(a) {
          stopAnimation();
          values = Array.from(a, Number);
          resetSortState();
          draw();
        },
        sortStep,
        sorted: isSorted
      };

      sortButton.addEventListener("click", animateSort);
      shuffleButton.addEventListener("click", shuffle);
      resetButton.addEventListener("click", () => {
        stopAnimation();
        values = initial.slice();
        resetSortState();
        draw();
      });

      draw();
    })();
  </script>
</body>
</html>
